import { useEffect, useState, type CSSProperties, type ReactNode, type MouseEvent } from "react";
import { OrgLegend } from "@/components/teams-org-legend";
import { TeamsCanvas } from "@/components/teams-canvas";
import { TeamsContextMenu } from "@/components/teams-context-menu";
import { TeamsInspector } from "@/components/teams-inspector";
import { TeamsOverview } from "@/components/teams-overview";

function Box({ children, className, style, onClick, onContextMenu, onMouseEnter, onMouseLeave, role }: {
  children?: ReactNode; className?: string; style?: CSSProperties;
  onClick?: (e: any) => void; onContextMenu?: (e: any) => void;
  onMouseEnter?: () => void; onMouseLeave?: () => void; role?: string;
}) {
  return <div className={className} role={role} onClick={onClick} onContextMenu={onContextMenu} onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave} style={style}>{children}</div>;
}
function Row({ children, gap = 0, align = "center", justify, style }: {
  children?: ReactNode; gap?: number; align?: "center" | "start" | "baseline"; justify?: "end" | "between"; style?: CSSProperties;
}) {
  return <div style={{ display: "flex", alignItems: align === "start" ? "flex-start" : align, justifyContent: justify === "end" ? "flex-end" : justify === "between" ? "space-between" : undefined, gap, ...style }}>{children}</div>;
}
function Stack({ children, gap = 0, style }: { children?: ReactNode; gap?: number; style?: CSSProperties }) {
  return <div style={{ display: "flex", flexDirection: "column", gap, ...style }}>{children}</div>;
}
function Text({ children, as: As = "span", size, weight, tone, mono, style, onClick }: {
  children?: ReactNode; as?: any; size?: number; weight?: number; tone?: "muted" | "dim" | "danger"; mono?: boolean; style?: CSSProperties; onClick?: () => void;
}) {
  const color = tone === "muted" ? "var(--fg-muted)" : tone === "dim" ? "var(--fg-dim)" : tone === "danger" ? "var(--danger)" : undefined;
  return <As className={mono ? "mono" : undefined} onClick={onClick} style={{ fontSize: size, fontWeight: weight, color, ...style }}>{children}</As>;
}
function ModalScrim({ children, onDismiss }: { children: ReactNode; onDismiss?: () => void }) {
  useEffect(() => {
    if (!onDismiss) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onDismiss(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onDismiss]);
  return (
    <div className="modal-scrim" style={{ position: "fixed", inset: 0, background: "color-mix(in oklch, black, transparent 45%)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}
      onMouseDown={(e: MouseEvent<HTMLDivElement>) => { if (e.target === e.currentTarget) onDismiss?.(); }}>
      {children}
    </div>
  );
}
function ModalButton({ children, variant, disabled, onClick }: { children: ReactNode; variant?: "primary"; disabled?: boolean; onClick?: () => void }) {
  return <button type="button" className={variant === "primary" ? "btn primary" : "btn ghost"} disabled={disabled} onClick={onClick}>{children}</button>;
}

interface Position { nodeId: string; kind: "agent" | "resource" | "external"; x: number; y: number; personaId?: string; label?: string }
interface Relationship { id: string; from: string; to: string; archetype: string; bow?: number }
interface Team { positions: Position[]; relationships: Relationship[] }
interface Persona { id: string; name: string; role?: string; blurb?: string; glyph?: string }
interface RelationshipArchetype {
  id: string; label: string; hue: number; style?: "solid" | "dashed" | "dotted"; bidirectional?: boolean; dashed?: boolean;
  fromLabel: string; toLabel: string; blurb: string;
  forward: { id: string; label: string; color: string; arrow: string }[];
  backward: { id: string; label: string; color: string; arrow: string }[];
}
interface Selection { type: "node" | "edge"; id: string }
interface TeamSummary { id: string; name: string; blurb: string; positions: { kind: "agent" | "resource" | "external" }[] }

function NewGroupDialog({
  title = "New item", description, placeholder = "Name", onCreate, onClose,
}: { title?: string; description?: string; placeholder?: string; onCreate: (name: string) => void; onClose: () => void }) {
  const [name, setName] = useState("");
  return (
    <ModalScrim onDismiss={onClose}>
      <Box style={{ width: 360, padding: 18, background: "var(--bg-panel)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", boxShadow: "0 20px 60px rgba(0,0,0,.5)" }}>
        <Text as="div" size={14} weight={600} style={{ marginBottom: 4 }}>{title}</Text>
        {description && <Text as="div" size={11.5} tone="muted" style={{ marginBottom: 12 }}>{description}</Text>}
        <input autoFocus className="input" placeholder={placeholder} value={name} onChange={(e) => setName(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && name.trim()) onCreate(name.trim()); }} style={{ width: "100%", marginBottom: 14, boxSizing: "border-box" }} />
        <Row gap={8} justify="end">
          <ModalButton onClick={onClose}>cancel</ModalButton>
          <ModalButton variant="primary" disabled={!name.trim()} onClick={() => onCreate(name.trim())}>create</ModalButton>
        </Row>
      </Box>
    </ModalScrim>
  );
}

const DEMO_PERSONAS: Persona[] = [
  { id: "p1", name: "builder-1", role: "engineer", blurb: "Implements features end to end, from the plan to a merged PR.", glyph: "\u25c6" },
  { id: "p2", name: "reviewer-2", role: "reviewer", blurb: "Reviews PRs and enforces scope.", glyph: "\u25c6" },
];
const DEMO_ARCHETYPES: RelationshipArchetype[] = [
  { id: "reports", label: "reports to", hue: 250, style: "solid", fromLabel: "report", toLabel: "manager",
    blurb: "Weekly status and blockers flow up this line.",
    forward: [{ id: "f1", label: "status update", color: "var(--accent)", arrow: "\u2192" }],
    backward: [{ id: "f2", label: "direction", color: "var(--accent)", arrow: "\u2192" }] },
  { id: "partners", label: "partners with", hue: 150, style: "dashed", bidirectional: true, dashed: true, fromLabel: "partner", toLabel: "partner",
    blurb: "Coordinates directly - shares context both ways.",
    forward: [{ id: "f3", label: "status update", color: "var(--success)", arrow: "\u2192" }],
    backward: [{ id: "f4", label: "status update", color: "var(--success)", arrow: "\u2192" }] },
];
const DEMO_ORGS: Record<string, Team> = {
  core: {
    positions: [
      { nodeId: "n1", kind: "agent", x: 40, y: 40, personaId: "p1" },
      { nodeId: "n2", kind: "agent", x: 320, y: 40, personaId: "p2" },
      { nodeId: "n3", kind: "resource", x: 180, y: 210, label: "Design system repo" },
    ],
    relationships: [
      { id: "r1", from: "n1", to: "n2", archetype: "partners" },
      { id: "r2", from: "n2", to: "n3", archetype: "reports" },
    ],
  },
  growth: {
    positions: [
      { nodeId: "g1", kind: "agent", x: 60, y: 60, personaId: "p2" },
      { nodeId: "g2", kind: "external", x: 340, y: 60, label: "Design partner" },
    ],
    relationships: [{ id: "gr1", from: "g1", to: "g2", archetype: "partners" }],
  },
};
const DEMO_TEAMS: TeamSummary[] = [
  { id: "core", name: "Core platform", blurb: "Builds and ships the main product surface.", positions: [{ kind: "agent" }, { kind: "agent" }, { kind: "resource" }] },
  { id: "growth", name: "Growth pod", blurb: "Partners with design on acquisition experiments.", positions: [{ kind: "agent" }, { kind: "external" }] },
];

export function TeamsPage() {
  const [teams, setTeams] = useState<TeamSummary[]>(DEMO_TEAMS);
  const [orgs, setOrgs] = useState<Record<string, Team>>(DEMO_ORGS);
  const [currentTeamId, setCurrentTeamId] = useState("core");
  const [sel, setSel] = useState<Selection>({ type: "node", id: "n1" });
  const [menu, setMenu] = useState<{ x: number; y: number; targetType: "node" | "edge"; targetId: string } | null>(null);
  const [creating, setCreating] = useState(false);

  const org = orgs[currentTeamId] ?? { positions: [], relationships: [] };

  const updateOrg = (fn: (t: Team) => Team) =>
    setOrgs((prev) => ({ ...prev, [currentTeamId]: fn(prev[currentTeamId] ?? { positions: [], relationships: [] }) }));

  const handleMoveNode = (nodeId: string, x: number, y: number) =>
    updateOrg((t) => ({ ...t, positions: t.positions.map((p) => (p.nodeId === nodeId ? { ...p, x, y } : p)) }));

  const handleDeletePosition = (nodeId: string) => {
    updateOrg((t) => ({
      positions: t.positions.filter((p) => p.nodeId !== nodeId),
      relationships: t.relationships.filter((r) => r.from !== nodeId && r.to !== nodeId),
    }));
    setSel({ type: "node", id: "" });
    setMenu(null);
  };
  const handleDeleteRelationship = (relId: string) => {
    updateOrg((t) => ({ ...t, relationships: t.relationships.filter((r) => r.id !== relId) }));
    setSel({ type: "node", id: "" });
    setMenu(null);
  };

  const handleEnterTeam = (teamId: string) => {
    setCurrentTeamId(teamId);
    const firstNode = (orgs[teamId] ?? DEMO_ORGS[teamId])?.positions[0];
    setSel(firstNode ? { type: "node", id: firstNode.nodeId } : { type: "node", id: "" });
    setMenu(null);
  };

  const overviewRows = Math.ceil(teams.length / 4) || 1;

  return (
    <Stack gap={16} style={{ padding: 20 }}>
      <Row align="center" justify="between">
        <Stack gap={2}>
          <Text as="h1" size={18} weight={600} style={{ margin: 0 }}>Teams</Text>
          <Text tone="muted" size={11}>{teams.length} team{teams.length === 1 ? "" : "s"} {"\u00b7"} org structure & relationships</Text>
        </Stack>
        <button className="btn primary" onClick={() => setCreating(true)}>+ new team</button>
      </Row>

      <Box style={{ position: "relative", height: overviewRows * 158 - 28 }}>
        <TeamsOverview teams={teams} onEnter={handleEnterTeam} />
      </Box>

      <Row gap={12} align="start" style={{ alignItems: "stretch" }}>
        <Box
          onClick={(e) => { if (e.target === e.currentTarget) setSel({ type: "node", id: "" }); }}
          onContextMenu={(e) => { e.preventDefault(); if (sel.id) setMenu({ x: e.clientX, y: e.clientY, targetType: sel.type, targetId: sel.id }); }}
          style={{ flex: "1.6 1 0", position: "relative", height: 420, borderRadius: 12, border: "1px solid var(--border-soft)", background: "var(--bg-panel)", overflow: "hidden" }}>
          <TeamsCanvas org={org} personas={DEMO_PERSONAS} archetypes={DEMO_ARCHETYPES} sel={sel}
            onSelectNode={(id) => setSel({ type: "node", id })}
            onSelectEdge={(id) => setSel({ type: "edge", id })}
            onMoveNode={handleMoveNode} />
          <OrgLegend archetypes={DEMO_ARCHETYPES} />
        </Box>
        <Box style={{ flex: "1 1 0", height: 420, borderRadius: 12, border: "1px solid var(--border-soft)", background: "var(--bg-panel)", overflow: "hidden", position: "relative" }}>
          <TeamsInspector org={org} personas={DEMO_PERSONAS} archetypes={DEMO_ARCHETYPES} sel={sel}
            onDeletePosition={handleDeletePosition} onDeleteRelationship={handleDeleteRelationship} />
        </Box>
      </Row>

      {menu && (
        <TeamsContextMenu x={menu.x} y={menu.y}
          deleteLabel={menu.targetType === "node" ? "Delete position" : "Delete relationship"}
          onDelete={() => (menu.targetType === "node" ? handleDeletePosition(menu.targetId) : handleDeleteRelationship(menu.targetId))}
          onClose={() => setMenu(null)} />
      )}
      {creating && (
        <NewGroupDialog title="New team" description="Give the new team a name - you can wire up its org chart after."
          placeholder="Team name" onClose={() => setCreating(false)}
          onCreate={(name) => {
            const id = name.toLowerCase().replace(/\s+/g, "-");
            setTeams((prev) => [...prev, { id, name, positions: [] }]);
            setOrgs((prev) => ({ ...prev, [id]: { positions: [], relationships: [] } }));
            setCurrentTeamId(id);
            setSel({ type: "node", id: "" });
            setCreating(false);
          }} />
      )}
    </Stack>
  );
}

